#include <cstdio>
#include <stdexcept>
#include <string>

struct Session {
    std::string id;
};

void authorise(const Session& s) {
    if (s.id.empty())
        throw std::runtime_error("missing id");
}

void handle(const std::string& id) {
    Session* s = new Session{id};
    authorise(*s);
    std::puts(s->id.c_str());
    delete s;
}

int main() {
    try { handle("a1"); } catch (...) {}
    try { handle(""); } catch (...) {}
}

