#include <algorithm>
#include <cstddef>

class Packet {
public:
    Packet(const std::byte* p, std::size_t n) : size_(n), data_(new std::byte[n]) {
        std::copy_n(p, n, data_);
    }

    Packet& operator=(const Packet& other) {
        std::byte* fresh = new std::byte[other.size_];
        delete[] data_;
        std::copy_n(other.data_, other.size_, fresh);
        size_ = other.size_;
        data_ = fresh;
        return *this;
    }

    ~Packet() { delete[] data_; }

private:
    std::size_t size_;
    std::byte* data_;
};

int main() {
    std::byte raw[8]{};
    Packet p{raw, 8};
    Packet& alias = p;
    p = alias;
}

#include <chrono>
#include <thread>
#include <vector>

class Sampler {
public:
    void start() {
        std::thread([this] {
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
            values_.push_back(1);
        }).detach();
    }

private:
    std::vector<int> values_;
};

int main() {
    {
        Sampler s;
        s.start();
    }
    std::this_thread::sleep_for(std::chrono::milliseconds(300));
}

#include <vector>

struct Sample {
    double v;
};

double smooth(std::vector<Sample>& xs) {
    Sample& first = xs.front();
    for (int i = 0; i < 64; ++i)
        xs.push_back(Sample{first.v});
    return first.v;
}

int main() {
    std::vector<Sample> xs{Sample{1.0}};
    return smooth(xs) > 0 ? 0 : 1;
}
